public class Student {
    // fields (state)
    private String name;
    private int yearLevel;

    // constructor
    public Student(String name, int yearLevel) {
        this.name = name;
        this.yearLevel = yearLevel;
    }

    // method (behaviour)
    public String getInfo() {
        return name + " - Year " + yearLevel;
    }
}

public class Main {
    public static void main(String[] args) {
        Student s1 = new Student("Ana Reyes", 2);
        Student s2 = new Student("Mark Santos", 2);

        System.out.println(s1.getInfo());
        System.out.println(s2.getInfo());
    }
}

// parent class
public class Person {
    protected String name;

    public Person(String name) {
        this.name = name;
    }

    public void greet() {
        System.out.println("Hello, " + name);
    }
}

// child class
public class Student extends Person {
    private String course;

    public Student(String name, String course) {
        super(name);          // call parent constructor
        this.course = course;
    }

    @Override
    public void greet() {
        System.out.println("Hi, I'm " + name + " from " + course);
    }
}

Person p1 = new Person("Mr. Cruz");
Person p2 = new Student("Liza Cruz", "BSIT");

p1.greet();  // Hello, Mr. Cruz
p2.greet();  // Hi, I'm Liza Cruz from BSIT

