import java.util.ArrayList;

public class ListDemo {
    public static void main(String[] args) {
        ArrayList<String> subjects = new ArrayList<>();

        subjects.add("OOP");
        subjects.add("Data Structures");
        subjects.add("Databases");

        System.out.println(subjects.size());     // 3
        System.out.println(subjects.get(0));     // OOP

        subjects.remove("OOP");

        for (String s : subjects) {
            System.out.println(s);
        }
    }
}

import java.util.HashMap;

public class MapDemo {
    public static void main(String[] args) {
        HashMap<String, Double> grades = new HashMap<>();

        grades.put("OOP", 1.50);
        grades.put("Data Structures", 1.75);
        grades.put("Databases", 1.25);

        System.out.println(grades.get("OOP"));   // 1.5

        for (String key : grades.keySet()) {
            System.out.println(key + " = " + grades.get(key));
        }
    }
}

import java.util.Scanner;

public class SafeInput {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        try {
            System.out.print("Enter a number: ");
            int n = Integer.parseInt(sc.nextLine());
            System.out.println("You entered: " + n);
        } catch (NumberFormatException e) {
            System.out.println("That was not a valid number.");
        } finally {
            sc.close();
        }
    }
}
